    expect(result.stdout).toContain('Top Tool Usage');
    expect(result.stdout).toContain('Bash');
    expect(result.stdout).toContain('Read');
  });

  // AC: @session-log-stats ac-6 (JSON)
  it('should output tool usage in JSON mode', () => {
